ref='34f88b8b02e1bd5428e4c1fff7cd9bd956964e2d';version='605f4784dc3e0337b7471162e74da6e2221db191';scientific='dbecc1f2d26db134ac7a817c6ce2b5d0ba05882a'
def obj(p,ref,file):return subprocess.check_output(['git','-C',str(p),'show',ref+':'+file])
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def read(p):return json.loads(p.read_bytes())
def save(p,d):p.write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
matrix='gold-review-consolidated-01/03_state_and_code/UNIFIED_EQUATION_TO_CODE_AND_QA.csv'
roles={'reg':'src/core/paper_a_regional.jl','form':'src/core/paper_a_formulations.jl','diag':'src/core/paper_a_diagnostics.jl','int':'src/core/paper_a_integration.jl','blocks':'src/core/block_variable.jl','con':'src/core/constraint.jl','obj':'src/core/objective.jl','model':'src/prob/uc_gscr_block_integration.jl','storage':'src/core/storage.jl','runner':'scripts/paper_a/run_week_strength_comparison.jl','week':'src/core/paper_a_full37.jl','adm':'scripts/paper_a/WeekStrengthAdmission.jl'}
def locs(block):
 out=[]
 for sel,a in block:
  path=roles[sel];old=obj(C,scientific,path);current=obj(C,version,path);assert current==old
  ids=[n for n,l in enumerate(current.decode().splitlines(),1) if a in l]; assert ids,(path,a);i=ids[0]
  out.append(f'{path}:{i}@{hashlib.sha256(current).hexdigest()}')
 return ';'.join(out)
